using Xunit;
using Moq;
using Microsoft.Extensions.Logging;
using NATS.Client.Core;
using NATS.Client.JetStream;
using NATS.Client.JetStream.Models;
using System;
using System.Threading;
using System.Threading.Tasks;

namespace Orleans.Streaming.NATS.Tests
{
    public class NatsConnectionManagerWrapper
    {
        private readonly NatsConnectionManager _natsConnectionManager;

        public NatsConnectionManagerWrapper(string providerName, ILoggerFactory loggerFactory, NatsOptions options)
        {
            _natsConnectionManager = new NatsConnectionManager(providerName, loggerFactory, options);
        }

        public Task Initialize(CancellationToken cancellationToken = default)
        {
            return _natsConnectionManager.Initialize(cancellationToken);
        }

        public Task EnqueueMessage(NatsStreamMessage message, CancellationToken cancellationToken = default)
        {
            return _natsConnectionManager.EnqueueMessage(message, cancellationToken);
        }
    }

    public class NatsConnectionManagerWrapperTests
    {
        [Fact]
        public async Task Initialize_ShouldLogError_WhenNatsConnectionFails()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<NatsConnectionManager>>();
            var natsConnectionMock = new Mock<NatsConnection>();
            var natsContextMock = new Mock<NatsJSContext>(natsConnectionMock.Object);
            var natsOptions = new NatsOptions { NatsClientOptions = NatsOpts.Default };
            var natsConnectionManagerWrapper = new NatsConnectionManagerWrapper("testProvider", loggerMock.Object, natsOptions);

            natsConnectionMock.Setup(x => x.ConnectAsync(It.IsAny<CancellationToken>()))
                .ThrowsAsync(new Exception("Connection failed"));

            // Act
            await natsConnectionManagerWrapper.Initialize(CancellationToken.None);

            // Assert
            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Error initializing NATS JetStream Connection Manager")),
                    It.IsAny<Exception>(),
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }

        [Fact]
        public async Task EnqueueMessage_ShouldLogError_WhenNatsContextIsNull()
        {
            // Arrange
            var loggerMock = new Mock<ILogger<NatsConnectionManager>>();
            var natsOptions = new NatsOptions { NatsClientOptions = NatsOpts.Default };
            var natsConnectionManagerWrapper = new NatsConnectionManagerWrapper("testProvider", loggerMock.Object, natsOptions);

            // Act & Assert
            await Assert.ThrowsAsync<InvalidOperationException>(() => natsConnectionManagerWrapper.EnqueueMessage(new NatsStreamMessage(), CancellationToken.None));

            loggerMock.Verify(
                x => x.Log(
                    LogLevel.Error,
                    It.IsAny<EventId>(),
                    It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Unable to enqueue message: NATS context is not initialized")),
                    null,
                    It.IsAny<Func<It.IsAnyType, Exception, string>>()),
                Times.Once);
        }
    }
}
